(async () => {
  const {set,calls,errors} = window.RELEASE_TEST;
  const q = s => document.querySelector(s);
  const all = s => [...document.querySelectorAll(s)];
  let passed = 0, failed = 0;
  const settle = async () => { for(let i=0;i<5;i++) await new Promise(requestAnimationFrame); };
  const check = async (name,fn) => {
    const item = document.createElement('li');
    try { await settle(); await fn(); item.className='pass';item.textContent='PASS · '+name;passed++; }
    catch(e) { item.className='fail';item.textContent='FAIL · '+name+': '+e.message;failed++; }
    q('#checks').append(item);
  };
  const expect = (condition,message) => { if(!condition) throw new Error(message); };
  const setAndWait = async values => { await set(values);await settle(); };
  await check('Professor ratings, GPA and withdrawal chips render',()=>expect(all('.prof-overlay__chip--rmp').length===2 && all('#primary .prof-overlay-host').length===3,'Missing/duplicated overlays'));
  await check('Course header supplies context to native rows without course cells',()=>expect(calls.filter(c=>c.type==='LOOKUP_PROFESSOR').every(c=>c.payload.courseCode==='COSC 1336'),'Missing course context'));
  await check('Unassigned instructor gets course-wide GPA and drop rate',()=>expect(q('#tba').textContent.includes('Course GPA 3.1') && q('#tba').textContent.includes('Course Drop Rate 10.3%'),'Missing fallback metrics'));
  await check('A clear Best Overall winner is highlighted',()=>expect(q('#a .prof-overlay__chip--best') && !q('#b .prof-overlay__chip--best'),'Wrong winner'));
  await check('Easiest A moves the recommendation to the higher-GPA instructor',async()=>{q('[data-mode=easiestA]').click();await settle();expect(q('#b .prof-overlay__chip--best')?.textContent==='Easiest A' && !q('#a .prof-overlay__chip--best'),'Ranking did not change');});
  await check('Lowest Risk moves the recommendation to the lower-withdrawal instructor',async()=>{q('[data-mode=lowestRisk]').click();await settle();expect(q('#a .prof-overlay__chip--best')?.textContent==='Lowest Risk','Wrong Lowest Risk winner');});
  await check('Chip clicks do not trigger native row navigation',()=>{let navigated=false;q('#a').addEventListener('click',()=>{navigated=true;},{once:true});const chip=q('#a .prof-overlay__chip--cg');chip.addEventListener('click',e=>e.preventDefault(),{once:true});chip.dispatchEvent(new MouseEvent('click',{bubbles:true,cancelable:true}));expect(!navigated,'Click reached the native row');});
  await check('Disabling both data sources removes old metrics, badges and course links',async()=>{await setAndWait({showRmp:false,showCougarGrades:false});expect(!q('.prof-overlay__chip--rmp')&&!q('.prof-overlay__chip--cg')&&!q('.prof-overlay__chip--best')&&!q('.prof-overlay--course-header'),'Disabled chips remained');});
  await check('Seat notice survives turning off data sources',()=>expect(q('#b').textContent.includes('2 seats left'),'Seat availability disappeared'));
  await check('Re-enabling data fetches newly enabled sources on the same page',async()=>{const before=calls.length;await setAndWait({showRmp:true,showCougarGrades:true});expect(calls.length>before && all('.prof-overlay__chip--rmp').length===2 && q('#tba .prof-overlay__chip--cg'),'Missing refreshed data');});
  await check('Removing a rival removes a best-of-one badge',async()=>{window.savedBeta=q('#b').cloneNode(true);window.savedBeta.querySelectorAll('.prof-overlay-host').forEach(n=>n.remove());q('#b').remove();await settle();expect(!q('#a .prof-overlay__chip--best'),'Stale rival kept a recommendation');});
  await check('Restoring a rival recalculates without duplicated overlays',async()=>{q('#results').append(window.savedBeta);await settle();expect(q('#a .prof-overlay__chip--best') && all('#a .prof-overlay-host').length===1,'Ranking failed after replacement');});
  await check('Changing text in the same instructor node replaces stale professor data',async()=>{q('#a [id*="SSR_INSTR_LONG"]').firstChild.nodeValue='Instructor Gamma';await settle();expect(q('#a').textContent.includes('Rating 4.1')&&!q('#a').textContent.includes('Rating 4.9'),'Old instructor data remained');});
  await check('A changed name releases its old row claim for another instructor node',async()=>{const cell=q('#a .instructor');const name=document.createElement('span');name.dataset.instructor='';name.textContent='Instructor Alpha';cell.append(name);await settle();try{expect(name.nextElementSibling?.textContent.includes('Rating 4.9'),'Old claim blocked the instructor: '+cell.textContent);}finally{name.remove();await settle();}});
  await check('Changing the same name node to TBA shows course fallback',async()=>{q('#a [id*="SSR_INSTR_LONG"]').textContent='To Be Announced';await settle();expect(q('#a').textContent.includes('Course GPA 3.1')&&!q('#a .prof-overlay__chip--rmp'),'Old professor chips remained on TBA');});
  await check('Same-node course header changes update links and lookup context',async()=>{q('#SSS_SUBJ_CATLG\\$0').firstChild.nodeValue='COSC1337';await settle();expect(q('.prof-overlay--course-header').textContent==='CG COSC 1337' && calls.at(-1).payload.courseCode==='COSC 1337','Course header did not update');});
  await check('Seat notice updates when availability changes',async()=>{q('#b .seats').textContent='Open Seats 28 of 130';await settle();expect(!q('#b .prof-overlay__chip--seats'),'Old seat warning remained');q('#b .seats').textContent='Open Seats 1 of 130';await settle();expect(q('#b .prof-overlay__chip--seats')?.textContent==='1 seat left','One-seat warning missing');});
  await check('Invalid stored selectors safely fall back to defaults',async()=>{await setAndWait({instructorSelector:'['});expect(all('#primary .prof-overlay-host').length===3,'Invalid selector broke rendering');});
  await check('Independent course sections use separate course contexts',async()=>{const section=q('#primary').cloneNode(true);section.id='secondary';section.querySelector('[id*="SSS_SUBJ_CATLG"]').id='SSS_SUBJ_CATLG$second';section.querySelector('[id*="SSS_SUBJ_CATLG"]').textContent='MATH 1331';section.querySelectorAll('.prof-overlay,.prof-overlay-host').forEach(n=>n.remove());section.querySelectorAll('[id]').forEach(n=>{n.id+='-second';});q('#scenarios').append(section);await settle();expect(calls.filter(c=>c.type==='LOOKUP_COURSE').some(c=>c.payload.courseCode==='MATH 1331') && section.textContent.includes('Course GPA 3.1'),'Course groups were mixed');});
  await check('A shared instructor row keeps its highlight when any instructor wins',async()=>{const section=document.createElement('section');section.innerHTML='<h2><span data-course-code>PHYS 1301</span></h2><table><tbody><tr id="team"><td><span data-instructor>Instructor Alpha</span><span data-instructor>Instructor Gamma</span></td><td>Open Seats 20 of 20</td></tr><tr><td><span data-instructor>Instructor Beta</span></td><td>Open Seats 20 of 20</td></tr></tbody></table>';q('#scenarios').append(section);await settle();section.querySelector('td:last-child').textContent='Open Seats 19 of 20';await settle();expect(q('#team .prof-overlay__chip--best') && q('#team').classList.contains('prof-overlay-best-row'),'Winner badge and row highlight disagree');await setAndWait({showRmp:false,showCougarGrades:false});expect(!q('#team').classList.contains('prof-overlay-best-row'),'Disabled rankings kept row highlight');await setAndWait({showRmp:true,showCougarGrades:true});});
  await check('Unknown-course rows do not receive misleading cross-course rankings',async()=>{const section=document.createElement('section');section.innerHTML='<table><tbody><tr><td><span data-instructor>Instructor Alpha</span></td></tr><tr><td><span data-instructor>Instructor Beta</span></td></tr></tbody></table>';q('#scenarios').append(section);await settle();expect(!section.querySelector('.prof-overlay__chip--best'),'Unidentified courses were ranked together');});
  await check('Dark mode applies immediately and restores the original theme',async()=>{await setAndWait({darkMode:true});expect(document.documentElement.classList.contains('profcheck-dark'),'Dark mode failed');expect(q('[role=switch]').checked,'Switch did not sync');await setAndWait({darkMode:false});expect(!document.documentElement.classList.contains('profcheck-dark'),'Light mode failed');});
  await check('Keyboard-style launcher activation focuses the ranking controls; Escape closes',async()=>{const toggle=q('.profcheck-launcher__toggle');toggle.click();expect(!q('.profcheck-panel').hidden && document.activeElement===q('.profcheck-panel__mode'),'Keyboard focus did not enter panel');document.activeElement.dispatchEvent(new KeyboardEvent('keydown',{key:'Escape',bubbles:true}));expect(q('.profcheck-panel').hidden && document.activeElement===toggle,'Escape did not restore focus');});
  await check('Transient API failure does not break existing rows or the launcher',async()=>{window.RELEASE_TEST.fail=true;const row=document.createElement('tr');row.innerHTML='<td>9</td><td><span data-instructor>Unavailable Instructor</span></td><td>Open Seats 25 of 25</td>';q('#results').append(row);await settle();expect(q('.profcheck-launcher__toggle') && q('#tba .prof-overlay__chip--cg'),'Outage broke working UI');window.RELEASE_TEST.fail=false;});
  await check('No uncaught exceptions, promise failures, or render errors',()=>expect(errors.length===0,errors.join('\n')));
  q('#summary').textContent=`${passed} browser checks passed · ${failed} failed`;
  q('#summary').dataset.failed=String(failed);
  q('#errors').textContent=errors.join('\n');
})();
